def _expected_lp_policy(profile_name: str) -> dict[str, Any]:
    """Build the complete expected LP policy for one reviewed curriculum profile.

    Parameters
    ----------
    profile_name
        Stable name of the curriculum profile under test.

    Returns
    -------
    dict[str, Any]
        Exact expected serialized LP policy.
    """

    checker_instructions, producer_instructions = _PROFILE_INSTRUCTIONS[profile_name]
    coordinate_statement_type, coordinate_values = _PROFILE_COORDINATES[profile_name]
    statement_types = _PROFILE_STATEMENT_TYPES[profile_name]

    return {
        "builds_towards": {
            "allowed_statement_type_pairs": [
                {
                    "source_statement_type": statement_type,
                    "target_statement_type": statement_type,
                }
                for statement_type in statement_types
            ]
        },
        "candidate_policy": deepcopy(_COMMON_CANDIDATE_POLICY),
        "checker_instructions": checker_instructions,
        "developmental_coordinate": {
            "ordered_values": list(coordinate_values),
            "statement_type": coordinate_statement_type,
        },
        "evidence_limits": deepcopy(_COMMON_EVIDENCE_LIMITS),
        "producer_instructions": producer_instructions,
        "relates_to": {
            "allowed_statement_type_pairs": [
                {
                    "first_statement_type": statement_type,
                    "second_statement_type": statement_type,
                }
                for statement_type in statement_types
            ]
        },
        "relationship_metadata": deepcopy(_COMMON_RELATIONSHIP_METADATA),
        "request_batch_size": 1,
        "retry": deepcopy(_COMMON_RETRY_POLICY),
        "unresolved_participation": "include_unresolved_with_warnings",
    }


def _load_profile_payload(profile_name: str = "ghana_math") -> dict[str, Any]:
    """Load a fresh runtime payload with a side-effect-free output location.

    Parameters
    ----------
    profile_name
        Stable name of the curriculum profile to load.

    Returns
    -------
    dict[str, Any]
        Parsed JSON runtime payload.
    """

    payload: dict[str, Any] = json.loads(
        _PROFILE_CONFIG_PATHS[profile_name].read_text(encoding="utf-8")
    )
    payload["page_ir_extraction"]["output_dir"] = str(PACKAGE_PATH / "backend/tests")
    payload["page_ir_extraction"]["pdf_fp"] = str(
        PACKAGE_PATH / "backend/tests/fixtures/utils/tanzania.pdf"
    )
    return payload


def _mapping_at_path(
    *, path: tuple[str | int, ...], payload: dict[str, Any]
) -> dict[str, Any]:
    """Return a mutable mapping at a nested runtime-config path.

    Parameters
    ----------
    path
        String keys and list indexes leading to the target mapping.
    payload
        Complete mutable runtime configuration.

    Returns
    -------
    dict[str, Any]
        Mutable mapping at the requested path.
    """

    current: Any = payload
    for part in path:
        current = current[part]

    assert isinstance(current, dict)
    return current


@PARAM(
    argnames=("profile_name",),
    argvalues=[(profile_name,) for profile_name in sorted(_PROFILE_CONFIG_PATHS)],
)
def test_all_six_profiles_match_complete_learning_progressions_policies(
    profile_name: str,
) -> None:
    """Every profile validates and exactly matches its complete reviewed LP policy.

    Parameters
    ----------
    profile_name
        Stable name of the curriculum profile under test.
    """

    parsed = RunConfig.model_validate(_load_profile_payload(profile_name))

    assert parsed.kgs is not None
    assert parsed.kgs.learning_progressions.model_dump() == _expected_lp_policy(
        profile_name
    )


def test_builds_towards_coordinate_type_may_supply_its_own_coordinate() -> None:
    """The coordinate statement type need not list itself in AS identity scope."""

    payload = _load_profile_payload()
    payload["kgs"]["lp"]["builds_towards"]["allowed_statement_type_pairs"] = [
        {"source_statement_type": "Grade", "target_statement_type": "Grade"}
    ]
    payload["kgs"]["lp"]["relates_to"]["allowed_statement_type_pairs"] = [
        {"first_statement_type": "Grade", "second_statement_type": "Grade"}
    ]

    parsed = RunConfig.model_validate(payload)

    assert parsed.kgs is not None
    pair = parsed.kgs.learning_progressions.builds_towards.allowed_statement_type_pairs[
        0
    ]
    assert pair.source_statement_type == "Grade"
    assert pair.target_statement_type == "Grade"


def test_builds_towards_type_without_coordinate_identity_scope_is_rejected() -> None:
    """A non-coordinate buildsTowards type must expose the coordinate in AS scope."""

    payload = _load_profile_payload()
    payload["kgs"]["as"]["identity_scope_statement_types"]["Indicator"] = ["Strand"]

    with pytest.raises(
        expected_exception=ValidationError,
        match="Every buildsTowards-participating statement type must expose",
    ):
        RunConfig.model_validate(payload)


def test_coordinate_order_is_preserved_for_complete_canonical_vocabulary() -> None:
    """Cross-validation preserves an explicitly configured canonical local order."""

    payload = _load_profile_payload()
    configured_order = ["BASIC 6", "BASIC 4", "BASIC 5"]
    payload["kgs"]["lp"]["developmental_coordinate"][
        "ordered_values"
    ] = configured_order

    parsed = RunConfig.model_validate(payload)

    assert parsed.kgs is not None
    assert (
        parsed.kgs.learning_progressions.developmental_coordinate.ordered_values
        == configured_order
    )


