def test_coordinate_statement_type_requires_local_grade_class_or_stage() -> None:
    """A known AS grouping cannot serve as the coordinate unless locally declared."""

    payload = _load_profile_payload()
    payload["kgs"]["lp"]["developmental_coordinate"]["statement_type"] = "Strand"

    with pytest.raises(
        expected_exception=ValidationError,
        match="must be declared by CreateKGConfig.as.grade_level_statement_types",
    ):
        RunConfig.model_validate(payload)


@PARAM(
    argnames=("donor_profile", "recipient_profile"),
    argvalues=list(permutations(sorted(_PROFILE_CONFIG_PATHS), 2)),
)
def test_cross_profile_learning_progressions_policy_copy_is_rejected(
    *, donor_profile: str, recipient_profile: str
) -> None:
    """No curriculum accepts another profile's complete LP policy unchanged.

    Parameters
    ----------
    donor_profile
        Curriculum whose LP section is copied.
    recipient_profile
        Different curriculum whose AS policy remains authoritative.
    """

    donor_payload = _load_profile_payload(donor_profile)
    recipient_payload = _load_profile_payload(recipient_profile)
    recipient_payload["kgs"]["lp"] = deepcopy(donor_payload["kgs"]["lp"])

    with pytest.raises(expected_exception=ValidationError):
        RunConfig.model_validate(recipient_payload)


def test_kgs_accepts_absent_namespace_only_when_entire_phase_is_skipped() -> None:
    """The LP namespace is required with kgs but kgs itself remains optional."""

    payload_without_kgs = _load_profile_payload()
    del payload_without_kgs["kgs"]
    assert RunConfig.model_validate(payload_without_kgs).kgs is None

    payload_without_lp = _load_profile_payload()
    del payload_without_lp["kgs"]["lp"]
    with pytest.raises(expected_exception=ValidationError) as exc_info:
        RunConfig.model_validate(payload_without_lp)

    assert any(
        error["loc"] == ("kgs", "lp") and error["type"] == "missing"
        for error in exc_info.value.errors()
    )


