def test_learning_progressions_statement_types_must_be_canonical_and_known(
    *, path: tuple[str | int, ...], value: str
) -> None:
    """AS aliases and unknown labels are not canonical LP statement-type policy.

    Parameters
    ----------
    path
        Location of one LP statement-type reference.
    value
        AS alias or unknown statement-type label under test.
    """

    payload = _load_profile_payload()
    field_name = path[-1]
    assert isinstance(field_name, str)
    _mapping_at_path(path=path[:-1], payload=payload)[field_name] = value

    with pytest.raises(
        expected_exception=ValidationError,
        match="must use canonical statement_type labels",
    ):
        RunConfig.model_validate(payload)


