def test_relates_to_only_type_without_coordinate_identity_scope_is_accepted() -> None:
    """Missing coordinate scope does not exclude an otherwise valid relatesTo type."""

    payload = _load_profile_payload()
    payload["kgs"]["as"]["identity_scope_statement_types"]["Indicator"] = ["Strand"]
    payload["kgs"]["lp"]["builds_towards"]["allowed_statement_type_pairs"] = [
        {
            "source_statement_type": "Content Standard",
            "target_statement_type": "Content Standard",
        }
    ]

    parsed = RunConfig.model_validate(payload)

    assert parsed.kgs is not None
    relates_to_types = {
        pair.first_statement_type
        for pair in parsed.kgs.learning_progressions.relates_to.allowed_statement_type_pairs
    }
    assert "Indicator" in relates_to_types


