def test_runtime_configuration_rejects_code_owned_invariant_overrides(
    *, field_name: str, path: tuple[str | int, ...], value: object
) -> None:
    """Full runtime loading rejects fields that attempt to override invariants.

    Parameters
    ----------
    field_name
        Unapproved runtime field under test.
    path
        Location where the field attempts to override code-owned behavior.
    value
        Representative override value.
    """

    payload = _load_profile_payload()
    _mapping_at_path(path=path, payload=payload)[field_name] = value

    with pytest.raises(expected_exception=ValidationError) as exc_info:
        RunConfig.model_validate(payload)

    assert any(
        error["loc"] == (*path, field_name) and error["type"] == "extra_forbidden"
        for error in exc_info.value.errors()
    )
